					pre[E.v]=i;
					cap[E.v]=min(cap[u],E.rem());
					if(!in_queue[E.v])q.push(E.v),in_queue[E.v]=1;
				}
			}
		}
		if(pre[t]<0)break;
		mxflow+=cap[t];mncost+=cap[t]*dist[t];
		for(int v=t;v!=s;v=e[pre[v]].u){
			e[pre[v]].flow+=cap[t];e[pre[v]^1].flow-=cap[t];
		}
	}
}
int main() {
  ios::sync_with_stdio(false);
	ll n,m,k,c,d;
  cin>>n>>m>>k>>c>>d;
	int MAXT=n+k;
	if(DEBUG)cout<<"MAXT: "<<MAXT<<endl;
	vector<int>a(k);
	fore(i,0,k){
		cin>>a[i];a[i]--;
		add_edge(SRC,a[i]*MAXT,1,0);
	}
	fore(j,0,MAXT)add_edge(j,SNC,k,0);
	fore(i,0,m) {
		int x,y;cin>>x>>y;x--,y--;
		fore(j,0,MAXT-1)fore(K,1,k+1) {
			add_edge(x*MAXT+j,y*MAXT+j+1,1,c+d*(2*K-1));
		}
		fore(j,0,MAXT-1)fore(K,1,k+1) {
			add_edge(y*MAXT+j,x*MAXT+j+1,1,c+d*(2*K-1));
		}
	}
	fore(i,0,n) {
		fore(j,0,MAXT-1)fore(K,1,k+1) {
			add_edge(i*MAXT+j,i*MAXT+j+1,1,c);
		}
	}
	flow(SRC,SNC);
